import {estimateClaimTime,formatCountdown} from './claim-time.js';
import {Contract,JsonRpcProvider,BrowserProvider,FetchRequest,formatUnits,parseUnits,isAddress,ZeroAddress} from './ethers.js';
const A='0xE8377eCb0F32f0C16025d5cF360D6C9e2EA66Adf',IMPL='0xC16439DD044bC747aeB9b2d0958c3Cd13f9d5B6c',CHAIN=20181205;
const FIXED_GAS_PRICE = 500_000_000_000n; // 500 Gwei
const TX_OVERRIDES = Object.freeze({ type: 0, gasPrice: FIXED_GAS_PRICE });
const $=id=>document.getElementById(id),abi=await (await fetch('./abi.json')).json();
let claimTimer;
let rpc,contract,state=null,user=null,signer=null,injected=null,dec=18,stakeDec=18,stakeSymbol='质押币',busy=false,loading=false,seq=0;
const erc=['function decimals() view returns(uint8)','function symbol() view returns(string)','function balanceOf(address) view returns(uint256)','function allowance(address,address) view returns(uint256)','function approve(address,uint256) returns(bool)'];
const proxyAbi=['function implementation() view returns(address)'];
const fmt=(v,d=dec)=>{const s=formatUnits(v,d),[a,b]=s.split('.');return BigInt(a).toLocaleString('en-US')+(b&&/[1-9]/.test(b)?'.'+b.replace(/0+$/,''):'');};
const exact=(v,d=dec)=>formatUnits(v,d),short=a=>a.slice(0,6)+'…'+a.slice(-4),put=(id,s)=>$(id).textContent=s;
function notify(s){put('toast',s);$('toast').hidden=false;clearTimeout(notify.t);notify.t=setTimeout(()=>$('toast').hidden=true,9000)}
function error(e){if(e.code===4001||e.code==='ACTION_REJECTED')return '已取消钱包操作';return e.reason||e.shortMessage||e.message||String(e)}
function provider(url){const req=new FetchRequest(url);req.timeout=16000;return new JsonRpcProvider(req,CHAIN,{staticNetwork:true,batchMaxCount:1})}
function setRPC(url){clearInterval(claimTimer);rpc=provider(url);contract=new Contract(A,abi,rpc);$('rpc').value=url;state=null;}
function amount(id,d=dec){const s=$(id).value.trim();if(!/^\d+(\.\d+)?$/.test(s))throw Error('请输入有效的正数');const v=parseUnits(s,d);if(v<=0n)throw Error('数量必须大于零');return v}
function address(id){const a=$(id).value.trim();if(!isAddress(a)||a===ZeroAddress)throw Error('请输入有效的非零地址');return a}
function bind(id,fn){$(id).onclick=()=>Promise.resolve().then(fn).catch(e=>notify(error(e)))}
function ask(title,body){put('confirmTitle',title);put('confirmText',body+'\n\nGas Price：固定 500 Gwei\n实际手续费 = Gas 用量 × 500 Gwei');return new Promise(resolve=>{const dlg=$('confirm');const done=v=>{dlg.close();resolve(v)};$('cancel').onclick=()=>done(false);$('proceed').onclick=()=>done(true);dlg.oncancel=e=>{e.preventDefault();done(false)};dlg.showModal()})}
function record(hash,label){const el=document.createElement('div');const a=document.createElement('a');a.href='https://scan.qki.dev/tx/'+hash;a.target='_blank';a.rel='noopener';a.textContent=label+' · '+short(hash)+' ↗';el.append(a);if($('history').children.length===0)$('history').textContent='';$('history').prepend(el);return a}
async function ensureWallet(){if(!user||!signer)throw Error('请先连接钱包');const chain=await injected.request({method:'eth_chainId'});if(BigInt(chain)!==BigInt(CHAIN))throw Error('请将钱包切换到 QKI 主网');const accounts=await injected.request({method:'eth_accounts'});if(accounts[0]?.toLowerCase()!==user.toLowerCase())throw Error('钱包账户已变更，请重新连接');const impl=await new Contract(A,proxyAbi,signer).implementation();if(impl.toLowerCase()!==IMPL.toLowerCase())throw Error('合约实现已升级，请更新界面后再交易');return new Contract(A,abi,signer)}
async function send(label,method,args=[],target=A,targetAbi=abi){if(busy)throw Error('请等待当前交易完成');busy=true;document.querySelectorAll('.action,#claim').forEach(x=>x.disabled=true);try{await ensureWallet();const c=new Contract(target,targetAbi,signer),fn=c.getFunction(method);await fn.staticCall(...args, TX_OVERRIDES);notify('请在钱包中确认：'+label);const tx=await fn(...args, TX_OVERRIDES),link=record(tx.hash,label+' · 等待确认');notify('交易已提交，等待链上确认');try{const receipt=await tx.wait(1,120000);if(!receipt||receipt.status!==1)throw Error('交易执行失败');link.textContent=label+' · 已确认 · '+short(tx.hash)+' ↗';notify(label+'已确认')}catch(e){link.textContent=label+' · 请在浏览器核对状态 · '+short(tx.hash)+' ↗';throw e}await refresh()}finally{busy=false;document.querySelectorAll('.action').forEach(x=>x.disabled=false);if(state)await checkClaim();}}
async function connect(){injected=window.ethereum||window.okxwallet;if(!injected)throw Error('未检测到钱包。电脑请启用 MetaMask / OKX 扩展；手机请在钱包内置浏览器打开。');const accounts=await injected.request({method:'eth_requestAccounts'});try{await injected.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x133f0d5'}]})}catch(e){if(e.code!==4902)throw e;await injected.request({method:'wallet_addEthereumChain',params:[{chainId:'0x133f0d5',chainName:'QKI Mainnet',nativeCurrency:{name:'QKI',symbol:'QKI',decimals:18},rpcUrls:[$('rpc').value],blockExplorerUrls:['https://scan.qki.dev']}]})}user=accounts[0];signer=await new BrowserProvider(injected).getSigner();put('connect',short(user));$('address').value=user;if(!connect.bound){connect.bound=true;injected.on?.('accountsChanged',()=>{user=null;signer=null;put('connect','重新连接钱包');$('claim').disabled=true;notify('钱包账户已变更，请重新连接');refresh()});injected.on?.('chainChanged',()=>{signer=null;user=null;put('connect','重新连接钱包');$('claim').disabled=true;notify('网络已变更，请重新连接钱包')})}await refresh()}
async function refresh(){if(loading)return;loading=true;const n=++seq;put('status','正在读取链上状态…');$('refresh').disabled=true;$('claim').disabled=true;try{const cid=await rpc.send('eth_chainId',[]);if(BigInt(cid)!==BigInt(CHAIN))throw Error('RPC 链 ID 不匹配');const block=await rpc.getBlock('latest');const observedAt=performance.now();const opts={blockTag:block.number};const names=['decimals','totalSupply','totalBurn','totalPower','totalUsersAmount','miningInitialized','miningEnabled','miningMintStopped','requireToken','anti_bot','epoch','burnTokenAmount','powerTierUnit','start_time','antiBotChangedAt'];const values=await Promise.all(names.map(k=>contract.getFunction(k)(opts)));const s=Object.fromEntries(names.map((k,i)=>[k,values[i]]));s.impl=await new Contract(A,proxyAbi,rpc).implementation(opts);s.block=block;s.observedAt=observedAt;dec=Number(s.decimals);const token=new Contract(s.requireToken,erc,rpc);[stakeDec,stakeSymbol]=await Promise.all([token.decimals(opts).then(Number),token.symbol(opts)]);if(n!==seq)return;state=s;
for(const [id,v] of [['supply',s.totalSupply],['burned',s.totalBurn],['totalPower',s.totalPower]]){const [whole,fraction]=exact(v).split('.');put(id,BigInt(whole).toLocaleString('en-US')+(fraction?'.'+fraction.slice(0,2).padEnd(2,'0'):''));$(id).title=exact(v)}put('users',s.totalUsersAmount.toString());put('mining',s.miningEnabled&&!s.miningMintStopped?'● 挖矿已开启':'○ 挖矿未开启 / 已停止');put('stakeToken',stakeSymbol+' · '+short(s.requireToken));$('stakeToken').title=s.requireToken;put('stakeLabel','已质押 · '+stakeSymbol);put('minimum',fmt(s.anti_bot,stakeDec)+' '+stakeSymbol);put('epoch',s.epoch+' 秒（约 '+(Number(s.epoch)/3600).toFixed(2)+' 小时）');put('burnRatio',exact(s.burnTokenAmount*10n**BigInt(dec),stakeDec)+' '+stakeSymbol+' / CCT');put('implementation',short(s.impl));$('implementation').title=s.impl;$('approveBtn').hidden=s.requireToken.toLowerCase()===A.toLowerCase();
const q=$('address').value.trim()||user;['balance','power','staked','frozen'].forEach(k=>put(k,'—'));put('tier','未查询');put('claimState','连接钱包后检查领取资格');clearInterval(claimTimer);put('timing','连接钱包或输入地址后，推算下次领取时间');put('claimCountdown','');put('claimHint','');put('unlock','');if(q){if(!isAddress(q))throw Error('查询地址格式不正确');const [bal,p,st,fr,last,claim,v1]=await Promise.all([contract.balanceOf(q,opts),contract.power(q,opts),contract.TokenBalanceOf(q,s.requireToken,opts),contract.freezeOf(q,opts),contract.last_miner(q,opts),contract.lastClaimTime(q,opts),contract.isV1(q,opts)]);Object.assign(s,{q,bal,p,st,last,claim,v1});put('balance',fmt(bal));put('power',fmt(p));put('staked',fmt(st,stakeDec));put('frozen',fmt(fr));put('tier',v1?'V1 · 需质押':'V2+');startClaimClock();put('unlock',claim>0n?'质押可提取时间：'+new Date(Number(claim+86400n)*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})+' (UTC+8)':'未有领取记录，提取以合约校验为准');await checkClaim();}
const changed=s.impl.toLowerCase()!==IMPL.toLowerCase();put('status',changed?'⚠ 实现合约已变更，请更新界面；交易已暂停':'● 已同步区块 '+block.number.toLocaleString()+' · '+new Date().toLocaleTimeString('zh-CN',{hour12:false}));
}catch(e){state=null;clearInterval(claimTimer);put('timing','预计下次可领取：—');put('claimCountdown','');put('claimHint','数据读取失败，请刷新后重新推算。');put('status','连接失败：'+error(e)+' · 可在底部更换 RPC');notify(error(e))}finally{loading=false;$('refresh').disabled=false}}
function startClaimClock(){
  clearInterval(claimTimer);
  const s=state;
  if(s.impl.toLowerCase()!==IMPL.toLowerCase()){
    put('timing','预计下次可领取：—');put('claimHint','合约实现已变更，请更新界面后推算。');return;
  }
  const estimate=estimateClaimTime(s);
  if(estimate.at===null){put('timing','预计下次可领取：—');put('claimHint',estimate.note);return;}
  put('timing','预计下次可领取：'+new Date(Number(estimate.at)*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})+' (UTC+8)');
  put('claimHint','按当前链上规则推算，最终以合约校验为准。');
  let wasWaiting=false;
  const tick=()=>{
    if(state!==s){clearInterval(claimTimer);return;}
    const chainNow=s.block.timestamp+Math.floor((performance.now()-s.observedAt)/1000);
    const remaining=Number(estimate.at)-chainNow;
    put('claimCountdown',remaining>0?'距离预计领取还有 '+formatCountdown(remaining):'已到预计领取时间，可刷新或检查领取资格');
    if(remaining<=0&&wasWaiting){wasWaiting=false;void checkClaim();}
    else if(remaining>0)wasWaiting=true;
  };
  tick();claimTimer=setInterval(tick,1000);
}
async function checkClaim(){const s=state;$('claim').disabled=true;if(!s?.q||!user||s.q.toLowerCase()!==user.toLowerCase()){put('claimState','查询为只读；请连接该地址的钱包后领取');return}if(s.impl.toLowerCase()!==IMPL.toLowerCase()){put('claimState','实现版本已变更，交易暂停');return}if(!s.miningEnabled||s.miningMintStopped){put('claimState','当前合约未开启挖矿');return}if(s.p===0n){put('claimState','暂无算力，请先燃烧 CCT 增加算力');return}if(s.v1&&s.st<s.anti_bot){put('claimState','质押不足最低要求');return}try{await contract.getFunction('mint()').staticCall({from:user});put('claimState','已满足领取条件');$('claim').disabled=busy}catch(e){put('claimState','暂不可领取：'+error(e))}}
bind('copyQq',async()=>{try{await navigator.clipboard.writeText('718614283');notify('已复制群号 718614283，打开 QQ 搜索“夸克新手村”即可加入。')}catch{notify('未能复制，请手动复制群号：718614283')}});
bind('connect',connect);bind('refresh',refresh);bind('query',refresh);
bind('saveRpc',async()=>{const url=new URL($('rpc').value.trim());if(url.protocol!=='https:')throw Error('请使用 HTTPS RPC');setRPC(url.href);localStorage.setItem('cctRpc',url.href);await refresh()});
bind('claim',async()=>{await ensureWallet();if(await ask('领取 CCT 奖励','领取会扣减相应算力，并将质押提取锁定至本次领取后的 24 小时。实际数量由合约计算。'))await send('领取奖励','mint()')});
bind('burnBtn',async()=>{const c=await ensureWallet(),v=amount('burnAmount');const [r,t,initialized]=await Promise.all([c.burnTokenAmount(),c.requireToken(),c.miningInitialized()]);const token=new Contract(t,erc,signer);const [d,sym]=await Promise.all([token.decimals(),token.symbol()]);if(await ask('确认燃烧 CCT','燃烧：'+exact(v)+' CCT\n新增算力：'+exact(initialized?v*3n:0n)+'\n额外消耗已质押：'+exact(initialized?v*r:0n,Number(d))+' '+sym+'\n符合条件时会先结算旧算力。燃烧不可撤销。'))await send('燃烧 CCT','burn',[v])});
bind('transferBtn',async()=>{const c=await ensureWallet(),to=address('recipient'),v=amount('transferAmount');const fee=await c.transfer_fee(user,v);if(await ask('确认转账','接收地址：'+to+'\n对方接收：'+exact(v)+' CCT\n额外手续费：'+exact(fee)+' CCT\n你的总扣款：'+exact(v+fee)+' CCT'))await send('转账','transfer',[to,v])});
async function stakeAction(kind){await ensureWallet();if(!state)throw Error('请先成功刷新合约数据');const token=state.requireToken,v=amount('stakeAmount',stakeDec);if(kind==='approve'){if(token.toLowerCase()===A.toLowerCase())throw Error('CCT 自质押无需授权');if(await ask('授权质押币','币种：'+stakeSymbol+'\n授权数量：'+exact(v,stakeDec)+'\n被授权合约：'+A+'\n授权完成后，还需要点击质押。'))await send('授权质押币','approve',[A,v],token,erc)}else{if(kind==='deposit'&&token.toLowerCase()!==A.toLowerCase()){const allowance=await new Contract(token,erc,signer).allowance(user,A);if(allowance<v)throw Error('授权额度不足，请先点击“授权本次数量”，确认后再质押')}if(await ask(kind==='deposit'?'确认质押':'确认提取',exact(v,stakeDec)+' '+stakeSymbol+(kind==='withdraw'?'\n提取可能影响 V1 领取资格，且需满足 24 小时锁定要求。':'\n按合约实际到账量记账。')))await send(kind==='deposit'?'质押':'提取',kind==='deposit'?'depositToken':'withdrawToken',[token,v])}}
bind('approveBtn',()=>stakeAction('approve'));bind('depositBtn',()=>stakeAction('deposit'));bind('withdrawBtn',()=>stakeAction('withdraw'));
bind('registerBtn',async()=>{await ensureWallet();const a=address('inviter');if(await ask('确认绑定邀请人',a+'\n绑定后不可修改。'))await send('绑定邀请人','registration',[a])});
for(const [id,fn,label] of [['freezeBtn','freeze','冻结'],['unfreezeBtn','unfreeze','解冻']])bind(id,async()=>{await ensureWallet();const v=amount('freezeAmount');if(await ask('确认'+label,exact(v)+' CCT'))await send(label,fn,[v])});
$('burnAmount').oninput=()=>{try{put('burnEstimate',fmt(amount('burnAmount')*3n))}catch{put('burnEstimate','—')}};
$('tabs').onclick=e=>{const tab=e.target.dataset.tab;if(!tab)return;document.querySelectorAll('#tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));for(const t of ['burn','stake','transfer','more'])$(t+'Pane').hidden=t!==tab};
$('explorer').href='https://scan.qki.dev/address/'+A;
setRPC(localStorage.getItem('cctRpc')||'https://hz.rpc.qkiscan.cn');await refresh();
